  "content": "매월 25일에 기준연금액(349,700원)과 국민연금 급여액 등을 고려하여 기초연금액을 지급합니다.* 25일이 토·공휴일인 경우에는 그 전 일에 지급&#13;기초연금액의 감액은 아래의 경우 이뤄집니다. &#13;(부부감액) 본인과 그 배우자가 모두 기초연금 수급권자인 경우에는 각각의 기초연금액에서 기초연금액의 20%를 감액&#13;(소득역전방지 감액) 소득인정액과 기초연금액(부부2인 수급가구는 부부감액 적용 이후)을 합산한 금액이 선정기준액 이상인 경우에는 선정기준액을 초과하는 금액의 범위에서 기초연금액의 일부를 감액&#13;",
  "criteria": "연령 : 만 65세이상인 자&#13;소득인정액 : 가구의 소득인정액이 선정기준액 이하인 자, 소득인정액은 아래와 같이 계산합니다.&#13;2026도 선정기준액은 단독가구는 2,470,000원, 부부가구는 3,952,000원&#13;소득인정액 = 소득평가액 + 재산의 소득환산액&#13;소득평가액 = {0.7 X (근로소득 - 116만원)} + 기타 소득&#13;재산의 소득환산액 = [ {(일반재산 - 기본재산액*) + (금융재산 - 2,000만원) - 부채} X 재산의 소득환산율 &amp;divide; 12월] + P**&#13; *…"
