  "content": "생활언어를 익히고 문화를 이해할 수 있도록 체계적이고 단계적으로 한국어 교육을 지원합니다.&#13;다문화가족을 대상으로 집합 또는 방문을 통해 다음과 같은 교육을 진행합니다. &#13;다문화가족 구성원간의 가족 내 역할을 익히고 가족문화에 대한 이해를 향상시키는 교육&#13;가족, 배우자, 부부, 자녀 등 대상을 세분화하여 대상에게 적합한 가족관계 증진교육&#13;언어, 문화차이 등으로 자녀양육에 어려움을 겪고 있는 결혼이민자를 위한 부모교육&#13;학업 성취가 낮고 자아발달 및 정서, 사회성 발달에 어려움을 겪고 있는 다문화가족의…",
