  "criteria": "근로소득 또는 사업소득 또는 종교인소득이 있는 거주자로서 아래 요건을 갖춘 경우 장려금 신청이 가능합니다.&#13;(공통사항 요건)&#13;1) 전년도 12월 31일 현재 대한민국 국적을 가진 자(외국인중에 대한민국 국적을 가진 자와 혼인한자, 대한민국 국적의 부양자녀가 있는 자 포함)일 것&#13;2) 전년도 중 다른 거주자의 부양자녀가 아닐 것3) 거주자(배우자 포함)가 전문직 사업을 영위하고 있는 자가 아닐 것&#13;(근로장려금 요건)&#13;1) 가구원 구성에 따른 가구 구분&#13;&amp;#9312; 단독가구 : 배우자…"
